import { useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useOrganization } from "@/lib/org/org-context";
import { SETTING_FLAGS, SETTING_OPTIONS, settingLabel } from "@/lib/sales/constants";
import { numeric, text, truthy, useSalesRead, useSalesWrite } from "@/components/sales/shared";
import { EmptyState, ErrorState, LoadingState } from "@/components/states";
import type { Json } from "@/integrations/supabase/types";

/**
 * Políticas operacionais de vendas.
 *
 * São as doze colunas que `sales_order_settings` guarda e que
 * `sales_settings_save` valida. Cada política é escrita pelo servidor: um valor
 * fora da lista é recusado, e a tela só oferece valores aceitos.
 */
export function SalesSettings({ organizationId }: { organizationId: string }) {
  const { hasPermission } = useOrganization();
  const [open, setOpen] = useState(false);
  const query = useSalesRead(organizationId, "settings");
  const [values, setValues] = useState<Record<string, string>>({});

  const write = useSalesWrite(organizationId, {
    onSuccess: () => {
      toast.success("Políticas atualizadas");
      setOpen(false);
      setValues({});
    },
  });

  if (!hasPermission("sales.configure")) return null;
  if (query.isPending) return <LoadingState label="Carregando políticas" />;
  if (query.error) {
    return <ErrorState description={query.error.message} onRetry={() => void query.refetch()} />;
  }

  const data = (query.data ?? {}) as Record<string, Json>;

  const submit = () => {
    const payload: Record<string, Json> = {};
    for (const [key, value] of Object.entries(values)) {
      payload[key] = key.endsWith("_hours") || key === "max_discount_percent" ? Number(value) : value;
    }
    write.mutate({ operation: "settings", values: payload });
  };

  return (
    <section className="space-y-5">
      <header>
        <h1 className="text-xl font-semibold">Políticas de vendas</h1>
        <p className="text-sm text-muted-foreground">
          Reserva não movimenta estoque. A obrigação financeira segue o gatilho configurado e
          nunca nasce de uma reserva. Pedido aprovado não é venda recebida.
        </p>
      </header>
      <div className="grid gap-4 lg:grid-cols-2">
        {Object.entries(SETTING_OPTIONS).map(([key, option]) => (
          <Card key={key}>
            <CardHeader>
              <CardTitle className="text-base">{option.label}</CardTitle>
              <CardDescription>{option.hint}</CardDescription>
            </CardHeader>
            <CardContent>
              <p className="text-sm font-medium">{settingLabel(key, data[key])}</p>
            </CardContent>
          </Card>
        ))}
        {Object.entries(SETTING_FLAGS).map(([key, option]) => (
          <Card key={key}>
            <CardHeader>
              <CardTitle className="text-base">{option.label}</CardTitle>
              <CardDescription>{option.hint}</CardDescription>
            </CardHeader>
            <CardContent>
              <p className="text-sm font-medium">{truthy(data[key]) ? "Sim" : "Não"}</p>
            </CardContent>
          </Card>
        ))}
        <Card>
          <CardHeader>
            <CardTitle className="text-base">Validade da reserva</CardTitle>
            <CardDescription>
              Horas em que uma reserva prende disponibilidade antes de expirar sozinha.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-sm font-medium">{numeric(data.reservation_expiry_hours)} horas</p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle className="text-base">Desconto máximo</CardTitle>
            <CardDescription>
              Em branco, vale a alçada de desconto do CRM. Nunca é o preço do item: o desconto é
              aplicado sobre a tabela oficial.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-sm font-medium">
              {text(data.max_discount_percent) === "" || data.max_discount_percent === null
                ? "Alçada do CRM"
                : `${numeric(data.max_discount_percent)}%`}
            </p>
          </CardContent>
        </Card>
      </div>
      <Button onClick={() => setOpen(true)}>Alterar políticas</Button>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Alterar políticas</DialogTitle>
            <DialogDescription>
              Deixe em branco o que não quiser mudar. O servidor valida cada valor antes de gravar.
            </DialogDescription>
          </DialogHeader>
          <form
            className="space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              submit();
            }}
          >
            {Object.entries(SETTING_OPTIONS).map(([key, option]) => (
              <div key={key} className="space-y-1">
                <Label htmlFor={`policy-${key}`}>{option.label}</Label>
                <select
                  id={`policy-${key}`}
                  className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
                  value={values[key] ?? ""}
                  onChange={(event) =>
                    setValues((current) => ({ ...current, [key]: event.target.value }))
                  }
                >
                  <option value="">Manter ({settingLabel(key, data[key])})</option>
                  {option.options.map((option_) => (
                    <option key={option_} value={option_}>
                      {option.labels[option_]}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-muted-foreground">{option.hint}</p>
              </div>
            ))}
            {Object.entries(SETTING_FLAGS).map(([key, option]) => (
              <div key={key} className="space-y-1">
                <Label htmlFor={`flag-${key}`}>{option.label}</Label>
                <select
                  id={`flag-${key}`}
                  className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
                  value={values[key] ?? ""}
                  onChange={(event) =>
                    setValues((current) => ({ ...current, [key]: event.target.value }))
                  }
                >
                  <option value="">Manter ({truthy(data[key]) ? "Sim" : "Não"})</option>
                  <option value="true">Sim</option>
                  <option value="false">Não</option>
                </select>
                <p className="text-xs text-muted-foreground">{option.hint}</p>
              </div>
            ))}
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-1">
                <Label htmlFor="policy-expiry">Validade da reserva (horas)</Label>
                <Input
                  id="policy-expiry"
                  type="number"
                  min="1"
                  max="8760"
                  placeholder={`Manter (${numeric(data.reservation_expiry_hours)})`}
                  value={values.reservation_expiry_hours ?? ""}
                  onChange={(event) =>
                    setValues((current) => ({
                      ...current,
                      reservation_expiry_hours: event.target.value,
                    }))
                  }
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="policy-discount">Desconto máximo (%)</Label>
                <Input
                  id="policy-discount"
                  type="number"
                  min="0"
                  max="100"
                  step="0.01"
                  placeholder="Em branco usa a alçada do CRM"
                  value={values.max_discount_percent ?? ""}
                  onChange={(event) =>
                    setValues((current) => ({
                      ...current,
                      max_discount_percent: event.target.value,
                    }))
                  }
                />
              </div>
            </div>
            {write.error ? (
              <p role="alert" className="text-sm text-destructive">
                {write.error.message}
              </p>
            ) : null}
            <DialogFooter>
              <Button
                type="button"
                variant="ghost"
                onClick={() => setOpen(false)}
                disabled={write.isPending}
              >
                Cancelar
              </Button>
              <Button type="submit" disabled={write.isPending || Object.keys(values).length === 0}>
                {write.isPending ? "Gravando…" : "Gravar políticas"}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </section>
  );
}

/** Estados padrão reaproveitados quando a área ainda não tem nada a exibir. */
export function SalesEmpty({ title, description }: { title: string; description: string }) {
  return <EmptyState title={title} description={description} />;
}

import { useState, type ReactNode } from "react";
import { Link } from "@tanstack/react-router";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { EmptyState, ErrorState, LoadingState } from "@/components/states";
import { PERMISSIONS } from "@/lib/rbac";
import {
  carrierModalityLabel,
  exceptionSeverityLabel,
  orderStatusLabel,
  reservationStatusLabel,
  returnStatusLabel,
  shipmentStatusLabel,
  stockStatusLabel,
  fulfillmentStatusLabel,
  settingLabel,
  CARRIER_MODALITY,
  ORDER_STATUS,
  RESERVATION_STATUS,
  SHIPMENT_STATUS,
  RETURN_STATUS,
  EXCEPTION_STATUS,
  EXCEPTION_SEVERITY,
  ACTIVE_RESERVATION_STATUS,
} from "@/lib/sales/constants";
import { SalesAction } from "@/components/sales/action";
import { NewOrder } from "@/components/sales/new-order";
import { SalesSettings } from "@/components/sales/settings";
import {
  isMoneyColumn,
  numeric,
  rows,
  text,
  truthy,
  useSalesList,
  useSalesRead,
  type Row,
} from "@/components/sales/shared";
import { money, str } from "@/components/crm/shared";

/**
 * Listagens do módulo de vendas.
 *
 * Cada área declara suas colunas e o rótulo de cada status; o servidor decide o
 * que a pessoa pode ver. Filtros enviados são apenas os que `sales_query`
 * entende — a tela não promete filtro que o backend não aplica.
 */
export type Area = {
  key: string;
  title: string;
  kind: string;
  permission: string;
  columns: string[];
  description: string;
};

export const AREAS: Area[] = [
  {
    key: "orders",
    title: "Pedidos",
    kind: "orders",
    permission: PERMISSIONS.salesOrdersRead,
    columns: [
      "order_number",
      "company_name",
      "order_date",
      "status",
      "stock_status",
      "fulfillment_status",
      "total_amount",
    ],
    description: "Pedido comercial não é venda recebida: o valor aqui não é faturamento.",
  },
  {
    key: "reservations",
    title: "Reservas",
    kind: "reservations",
    permission: PERMISSIONS.reservationsRead,
    columns: ["order_number", "sku_snapshot", "location_name", "quantity", "status"],
    description:
      "Reserva não movimenta estoque: torna a mercadoria indisponível para os demais pedidos.",
  },
  {
    key: "fulfillment",
    title: "Separação e embalagem",
    kind: "fulfillment",
    permission: PERMISSIONS.fulfillmentRead,
    columns: ["fulfillment_number", "order_number", "source_location_name", "status"],
    description: "Separa, confere e embala. Conferir não baixa estoque; expedir baixa.",
  },
  {
    key: "shipments",
    title: "Expedições",
    kind: "shipments",
    permission: PERMISSIONS.shipmentsRead,
    columns: ["shipment_number", "order_number", "status", "tracking_code", "delivered_quantity"],
    description: "A expedição é a única etapa do ciclo que dá baixa oficial no estoque.",
  },
  {
    key: "returns",
    title: "Devoluções",
    kind: "returns",
    permission: PERMISSIONS.returnsRead,
    columns: ["return_number", "order_number", "status", "reason"],
    description: "Receber devolução devolve mercadoria ao estoque; o estorno financeiro fica pedido.",
  },
  {
    key: "exceptions",
    title: "Ocorrências",
    kind: "exceptions",
    permission: PERMISSIONS.logisticsRead,
    columns: ["order_number", "message", "severity", "status"],
    description: "Divergência de separação, atraso e problema de entrega ficam registrados aqui.",
  },
  {
    key: "carriers",
    title: "Transportadoras",
    kind: "carriers",
    permission: PERMISSIONS.shipmentsRead,
    columns: ["name", "modality", "status"],
    description: "Cadastro usado nas expedições. Não há integração com transportadora externa.",
  },
];

const STATUS_LABELS: Record<string, (value: unknown) => string> = {
  orders: orderStatusLabel,
  reservations: reservationStatusLabel,
  fulfillment: fulfillmentStatusLabel,
  shipments: shipmentStatusLabel,
  returns: returnStatusLabel,
  exceptions: (value) =>
    text(value) === "" ? "—" : (EXCEPTION_STATUS[text(value)] ?? text(value)),
  carriers: (value) => (text(value) === "ACTIVE" ? "Ativa" : text(value) === "INACTIVE" ? "Inativa" : "—"),
};

const STATUS_MAPS: Record<string, Record<string, string>> = {
  orders: { ...ORDER_STATUS, stock_status: "", fulfillment_status: "" },
  reservations: RESERVATION_STATUS,
  fulfillment: {},
  shipments: SHIPMENT_STATUS,
  returns: RETURN_STATUS,
  exceptions: { ...EXCEPTION_STATUS, ...EXCEPTION_SEVERITY },
  carriers: {},
};

const COLUMN_LABELS: Record<string, string> = {
  order_number: "Pedido",
  shipment_number: "Expedição",
  return_number: "Devolução",
  fulfillment_number: "Atendimento",
  company_name: "Cliente",
  order_date: "Data do pedido",
  status: "Status",
  stock_status: "Estoque",
  fulfillment_status: "Atendimento",
  total_amount: "Valor do pedido",
  sku_snapshot: "SKU",
  location_name: "Local",
  source_location_name: "Origem",
  quantity: "Quantidade",
  delivered_quantity: "Entregue",
  tracking_code: "Rastreio",
  message: "Ocorrência",
  severity: "Gravidade",
  name: "Nome",
  modality: "Modalidade",
  reason: "Motivo",
};

/** Cartão de uma linha de listagem, no formato usado pelas demais áreas. */
export function RecordCards({
  data,
  columns,
  area,
  children,
}: {
  data: Row[];
  columns: string[];
  area: string;
  children?: (row: Row) => ReactNode;
}) {
  if (data.length === 0) {
    return (
      <EmptyState
        title="Nenhum registro"
        description="Ajuste os filtros ou registre o primeiro documento desta área."
      />
    );
  }
  return (
    <div className="grid gap-3 lg:grid-cols-2">
      {data.map((row, index) => (
        <Card key={text(row.id) || index}>
          <CardContent className="space-y-3 pt-6">
            <dl className="grid grid-cols-2 gap-2">
              {columns.map((column) => (
                <div key={column}>
                  <dt className="text-xs text-muted-foreground">
                    {COLUMN_LABELS[column] ?? column}
                  </dt>
                  <dd className="break-words text-sm">
                    <Cell column={column} value={row[column]} area={area} />
                  </dd>
                </div>
              ))}
            </dl>
            {children?.(row)}
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

function Cell({ column, value, area }: { column: string; value: unknown; area: string }) {
  if (column === "status" || column === "severity" || column === "modality") {
    const map = STATUS_MAPS[area] ?? {};
    const label = STATUS_LABELS[area]?.(value) ?? map[text(value)] ?? text(value);
    return label === "—" ? (
      <span className="text-muted-foreground">—</span>
    ) : (
      <Badge variant="outline" className="font-normal">
        {label}
      </Badge>
    );
  }
  if (column === "stock_status") return <span>{stockStatusLabel(value)}</span>;
  if (column === "fulfillment_status") return <span>{fulfillmentStatusLabel(value)}</span>;
  if (isMoneyColumn(column)) return <span>{money(value)}</span>;
  return <span>{str(value)}</span>;
}

const PAGE_SIZE = 30;

export function SalesArea({ organizationId, area }: { organizationId: string; area: Area }) {
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("");
  const [page, setPage] = useState(0);
  const list = useSalesList(organizationId, area.kind, {
    search,
    status,
    limit: PAGE_SIZE,
    offset: page * PAGE_SIZE,
  });

  if (list.query.isPending) return <LoadingState label={`Carregando ${area.title.toLowerCase()}`} />;
  if (list.query.error) {
    return (
      <ErrorState
        description={list.query.error.message}
        onRetry={() => void list.query.refetch()}
      />
    );
  }

  const total = list.total;
  const pages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const hasSearch = area.kind === "orders" || area.kind === "exceptions";

  return (
    <section className="space-y-4">
      <header>
        <h1 className="text-xl font-semibold">{area.title}</h1>
        <p className="text-sm text-muted-foreground">{area.description}</p>
      </header>
      <div className="flex flex-wrap gap-2">
        {area.key === "orders" ? <NewOrder organizationId={organizationId} /> : null}
        {area.key === "reservations" ? (
          <SalesAction
            organizationId={organizationId}
            label="Processar reservas vencidas"
            permission={PERMISSIONS.reservationsRelease}
            operation="expire"
            description="Expirar devolve a disponibilidade. Nenhum saldo físico é mexido."
          />
        ) : null}
        {area.key === "carriers" ? (
          <SalesAction
            organizationId={organizationId}
            label="Nova transportadora"
            permission={PERMISSIONS.carriersManage}
            operation="carrier"
            fields={[
              { key: "name", label: "Nome", required: true },
              {
                key: "document_type",
                label: "Documento",
                options: ["CNPJ", "CPF", "OTHER"],
                optionLabels: { CNPJ: "CNPJ", CPF: "CPF", OTHER: "Outro" },
              },
              { key: "document_number", label: "Número do documento" },
              { key: "contact_name", label: "Pessoa de contato" },
              { key: "contact_phone", label: "Telefone" },
              {
                key: "modality",
                label: "Modalidade",
                options: Object.keys(CARRIER_MODALITY),
                optionLabels: CARRIER_MODALITY,
                hint: "Em branco, a transportadora é registrada como courier.",
              },
            ]}
          />
        ) : null}
      </div>
      <div className="flex flex-wrap gap-2">
        {hasSearch ? (
          <Input
            className="max-w-xs"
            aria-label={area.key === "orders" ? "Buscar pedido" : "Buscar ocorrência"}
            placeholder={area.key === "orders" ? "Número ou observação" : "Mensagem"}
            value={search}
            onChange={(event) => {
              setSearch(event.target.value);
              setPage(0);
            }}
          />
        ) : null}
        <Input
          className="max-w-[14rem]"
          aria-label="Filtrar por status"
          placeholder="Status (ex.: DRAFT)"
          value={status}
          onChange={(event) => {
            setStatus(event.target.value.toUpperCase());
            setPage(0);
          }}
        />
      </div>
      <RecordCards data={list.rows} columns={area.columns} area={area.key}>
        {(row) => (
          <div className="flex flex-wrap gap-2">
            {row.sales_order_id || area.key === "orders" ? (
              <Link
                className="text-sm text-primary underline"
                to="/vendas/pedidos/$id"
                params={{ id: text(area.key === "orders" ? row.id : row.sales_order_id) }}
              >
                Abrir pedido
              </Link>
            ) : null}
            {area.key === "reservations" &&
            (text(row.status) === "ACTIVE" || text(row.status) === "PARTIALLY_CONSUMED") ? (
              <SalesAction
                organizationId={organizationId}
                label="Liberar reserva"
                permission={PERMISSIONS.reservationsRelease}
                operation="reservation"
                action="release"
                id={text(row.id)}
                fields={[{ key: "reason", label: "Motivo", required: true }]}
                description="Liberar devolve a disponibilidade para os demais pedidos."
              />
            ) : null}
            {area.key === "exceptions" && text(row.status) === "OPEN" ? (
              <SalesAction
                organizationId={organizationId}
                label="Resolver ocorrência"
                permission={PERMISSIONS.logisticsExceptions}
                operation="exception"
                action="resolve"
                id={text(row.id)}
                fields={[{ key: "resolution", label: "Resolução", type: "textarea", required: true }]}
              />
            ) : null}
            {area.key === "carriers" ? (
              <CarrierEditor organizationId={organizationId} carrier={row} />
            ) : null}
          </div>
        )}
      </RecordCards>
      {pages > 1 ? (
        <div className="flex items-center gap-3">
          <Button variant="outline" disabled={page === 0} onClick={() => setPage((p) => p - 1)}>
            Anterior
          </Button>
          <span className="text-sm text-muted-foreground">
            Página {page + 1} de {pages} · {total} registros
          </span>
          <Button
            variant="outline"
            disabled={(page + 1) * PAGE_SIZE >= total}
            onClick={() => setPage((p) => p + 1)}
          >
            Próxima
          </Button>
        </div>
      ) : null}
    </section>
  );
}

function CarrierEditor({ organizationId, carrier }: { organizationId: string; carrier: Row }) {
  return (
    <SalesAction
      organizationId={organizationId}
      label="Editar"
      permission={PERMISSIONS.carriersManage}
      operation="carrier"
      id={text(carrier.id)}
      initial={carrier}
      fields={[
        { key: "name", label: "Nome", required: true },
        {
          key: "document_type",
          label: "Documento",
          options: ["CNPJ", "CPF", "OTHER"],
          optionLabels: { CNPJ: "CNPJ", CPF: "CPF", OTHER: "Outro" },
        },
        { key: "document_number", label: "Número do documento" },
        { key: "contact_name", label: "Pessoa de contato" },
        { key: "contact_phone", label: "Telefone" },
        {
          key: "modality",
          label: "Modalidade",
          options: Object.keys(CARRIER_MODALITY),
          optionLabels: CARRIER_MODALITY,
        },
        {
          key: "status",
          label: "Situação",
          options: ["ACTIVE", "INACTIVE"],
          optionLabels: { ACTIVE: "Ativa", INACTIVE: "Inativa" },
        },
      ]}
    />
  );
}

/** Indicadores do período. Valores de pedido não são recebimento. */
export function SalesDashboard({ organizationId }: { organizationId: string }) {
  const query = useSalesRead(organizationId, "dashboard");
  if (query.isPending) return <LoadingState label="Carregando indicadores" />;
  if (query.error) {
    return (
      <ErrorState description={query.error.message} onRetry={() => void query.refetch()} />
    );
  }
  const data = (query.data ?? {}) as Record<string, Json>;
  const indicators: [string, string, boolean?][] = [
    ["orders_total", "Pedidos no período"],
    ["amount_total", "Valor dos pedidos", true],
    ["awaiting_approval", "Aguardando aprovação"],
    ["awaiting_stock", "Aguardando estoque"],
    ["shipments_in_transit", "Expedições em trânsito"],
    ["shipments_overdue", "Entregas atrasadas"],
    ["returns_pending", "Devoluções pendentes"],
    ["open_exceptions", "Ocorrências abertas"],
  ];
  return (
    <section className="space-y-4">
      <header>
        <h1 className="text-xl font-semibold">Indicadores de vendas</h1>
        <p className="text-sm text-muted-foreground">
          Período de {text(data.from) || "—"} a {text(data.to) || "—"}. Valor de pedido não é
          faturamento nem recebimento.
        </p>
      </header>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {indicators.map(([key, title, isMoney]) => (
          <Card key={key}>
            <CardContent className="pt-6">
              <p className="text-sm text-muted-foreground">{title}</p>
              <p className="text-2xl font-semibold">
                {isMoney ? money(data[key]) : numeric(data[key])}
              </p>
            </CardContent>
          </Card>
        ))}
      </div>
    </section>
  );
}

/** Área de crédito do cliente, lida do CRM com permissão própria. */
export function SalesCredits({ organizationId }: { organizationId: string }) {
  const list = useSalesList(organizationId, "credits", { limit: PAGE_SIZE });
  if (list.query.isPending) return <LoadingState label="Carregando crédito" />;
  if (list.query.error) {
    return (
      <ErrorState
        description={list.query.error.message}
        onRetry={() => void list.query.refetch()}
      />
    );
  }
  return (
    <section className="space-y-4">
      <header>
        <h1 className="text-xl font-semibold">Crédito do cliente</h1>
        <p className="text-sm text-muted-foreground">
          Limite, uso e decisão de bloqueio. O servidor reavalia o crédito no momento da aprovação;
          a tela apenas mostra o que foi avaliado.
        </p>
      </header>
      <RecordCards
        data={list.rows}
        columns={["company_name", "credit_limit", "used_amount", "available_amount", "decision"]}
        area="credits"
      />
    </section>
  );
}

export { SalesSettings, truthy, rows, settingLabel, carrierModalityLabel, exceptionSeverityLabel, ACTIVE_RESERVATION_STATUS };

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { EmptyState, ErrorState, LoadingState } from "@/components/states";
import { PERMISSIONS } from "@/lib/rbac";
import { money, str } from "@/components/crm/shared";
import { SalesAction, type ActionItem } from "@/components/sales/action";
import {
  numeric,
  object,
  rows,
  text,
  useSalesRead,
  type Row,
} from "@/components/sales/shared";
import {
  CARRIER_MODALITY,
  DELIVERED_SHIPMENT_STATUS,
  IN_TRANSIT_SHIPMENT_STATUS,
  OPEN_ORDER_STATUS,
  RETURN_DESTINATION,
  fulfillmentActions,
  fulfillmentStatusLabel,
  isOneOf,
  orderActions,
  orderStatusLabel,
  pickingStatusLabel,
  reservationStatusLabel,
  returnDestinationLabel,
  returnStatusLabel,
  shipmentStatusLabel,
  stockStatusLabel,
} from "@/lib/sales/constants";

/**
 * Detalhe de um pedido de venda.
 *
 * Reúne o que é fato (itens, disponibilidade oficial, reservas, atendimento,
 * expedições, devoluções, recebíveis, movimentos do ledger e histórico) e as
 * ações possíveis no estado atual. A tela não decide o que é possível: ela lê o
 * status devolvido pelo servidor e oferece a ação correspondente; quem valida,
 * com permissão e regra, continua sendo a RPC.
 */
export function OrderDetail({ organizationId, orderId }: { organizationId: string; orderId: string }) {
  const query = useSalesRead(organizationId, "detail", orderId);
  const locations = useSalesRead(organizationId, "locations");

  if (query.isPending) return <LoadingState label="Carregando pedido" />;
  if (query.error) {
    return <ErrorState description={query.error.message} onRetry={() => void query.refetch()} />;
  }

  const data = object(query.data);
  const order = object(data.order);
  const status = text(order.status);
  const actions = orderActions(status);
  const locationChoices = rows(locations.data).map((row) => ({
    key: text(row.id),
    label: `${str(row.name)}${row.type ? ` · ${str(row.type)}` : ""}`,
  }));
  const sourceField = {
    key: "source_location_id",
    label: "Localização de origem",
    required: true,
    options: locationChoices.map((choice) => choice.key),
    optionLabels: Object.fromEntries(locationChoices.map((choice) => [choice.key, choice.label])),
  };

  return (
    <div className="space-y-6">
      <header className="space-y-1">
        <h1 className="text-xl font-semibold">
          {str(order.order_number)} · {str(object(data.company).legal_name || object(data.company).trade_name)}
        </h1>
        <div className="flex flex-wrap items-center gap-2">
          <Badge variant="outline">{orderStatusLabel(status)}</Badge>
          <span className="text-sm text-muted-foreground">
            Estoque: {stockStatusLabel(order.stock_status)}
          </span>
        </div>
        <p className="text-sm">
          Total do pedido: <strong>{money(order.total_amount)}</strong>
        </p>
        {order.expected_delivery_date ? (
          <p className="text-sm text-muted-foreground">
            Previsão de entrega: {str(order.expected_delivery_date)}
          </p>
        ) : null}
        {str(order.commercial_notes) === "—" ? null : (
          <p className="text-sm text-muted-foreground">Observações: {str(order.commercial_notes)}</p>
        )}
      </header>

      <OrderActions
        organizationId={organizationId}
        orderId={orderId}
        status={status}
        actions={actions}
        sourceField={sourceField}
        items={rows(data.items)}
      />

      <Section title="Itens do pedido" description="Preço e quantidade vêm da tabela oficial e da proposta aceita; a tela não permite digitá-los.">
        <Table
          data={rows(data.items)}
          columns={[
            ["sku_snapshot", "SKU"],
            ["description_snapshot", "Descrição"],
            ["ordered_quantity", "Pedido"],
            ["unit_price", "Preço"],
            ["reserved_quantity", "Reservado"],
            ["fulfilled_quantity", "Expedido"],
            ["delivered_quantity", "Entregue"],
            ["returned_quantity", "Devolvido"],
          ]}
        />
      </Section>

      <Section
        title="Disponibilidade oficial"
        description="Saldo físico menos reservas. Consultar disponibilidade não reserva nem movimenta mercadoria."
      >
        <Table
          data={rows(object(data.availability).items).map((row) => ({
            ...row,
            sku: row.sku ?? row.sku_snapshot,
            available: row.available ?? row.available_quantity,
          }))}
          columns={[
            ["sku", "SKU"],
            ["available", "Disponível"],
            ["reserved", "Reservado"],
            ["on_hand", "Saldo físico"],
          ]}
        />
      </Section>

      <Section title="Reservas" description="Reserva prende disponibilidade; não é baixa de estoque.">
        <Table
          data={rows(data.reservations)}
          columns={[
            ["sku_snapshot", "SKU"],
            ["location_name", "Local"],
            ["quantity", "Reservado"],
            ["status", "Situação"],
          ]}
          render={(row) => reservationStatusLabel(row.status)}
        />
      </Section>

      <Fulfillments
        organizationId={organizationId}
        orderId={orderId}
        fulfillments={rows(data.fulfillments)}
        tasks={rows(data.picking_tasks)}
        picks={rows(data.picking_items)}
      />

      <Section title="Expedições e entregas" description="A expedição é a etapa que dá baixa oficial no estoque, uma única vez.">
        <Table
          data={rows(data.shipments)}
          columns={[
            ["shipment_number", "Expedição"],
            ["status", "Situação"],
            ["tracking_code", "Rastreio"],
            ["delivered_quantity", "Entregue"],
          ]}
          render={(row) => shipmentStatusLabel(row.status)}
        >
          {(shipment) => (
            <ShipmentActions
              organizationId={organizationId}
              orderId={orderId}
              shipment={shipment}
              shipmentItems={rows(data.shipment_items).filter(
                (item) => text(item.shipment_id) === text(shipment.id),
              )}
            />
          )}
        </Table>
      </Section>

      <Returns
        organizationId={organizationId}
        returns={rows(data.returns)}
        returnItems={rows(data.return_items)}
        locationChoices={locationChoices}
      />

      {rows(data.receivables).length > 0 ? (
        <Section
          title="Recebíveis"
          description="Gerados pelo gatilho financeiro configurado. Obrigação em aberto não é recebimento."
        >
          <Table
            data={rows(data.receivables)}
            columns={[
              ["status", "Situação"],
              ["original_amount", "Valor original"],
              ["open_amount", "Em aberto"],
            ]}
          />
        </Section>
      ) : null}

      <Section title="Movimentos oficiais de estoque" description="Derivados do ledger; nunca editados.">
        <Table
          data={rows(data.movements)}
          columns={[
            ["created_at", "Data"],
            ["sku_snapshot", "SKU"],
            ["quantity", "Quantidade"],
            ["status", "Situação"],
          ]}
        />
      </Section>

      <Section title="Histórico" description="Transições registradas pelo servidor.">
        <Table
          data={rows(data.history)}
          columns={[
            ["created_at", "Data"],
            ["action", "Ação"],
            ["previous_status", "Anterior"],
            ["new_status", "Novo"],
          ]}
        />
      </Section>
    </div>
  );
}

function OrderActions({
  organizationId,
  orderId,
  status,
  actions,
  sourceField,
  items,
}: {
  organizationId: string;
  orderId: string;
  status: string;
  actions: string[];
  sourceField: { key: string; label: string; required?: boolean; options: string[]; optionLabels: Record<string, string> };
  items: Row[];
}) {
  const reason = { key: "reason", label: "Motivo", type: "textarea" as const, required: true };
  const open = isOneOf(status, OPEN_ORDER_STATUS);

  return (
    <div className="flex flex-wrap gap-2">
      {actions.includes("submit") ? (
        <SalesAction
          organizationId={organizationId}
          label="Enviar para aprovação"
          permission={PERMISSIONS.salesOrdersUpdate}
          operation="order"
          id={orderId}
          action="submit"
          description="Enviar não aprova. A aprovação é de outro usuário quando a segregação está ativa."
        />
      ) : null}
      {actions.includes("approve") ? (
        <SalesAction
          organizationId={organizationId}
          label="Aprovar pedido"
          permission={PERMISSIONS.salesOrdersApprove}
          operation="order"
          id={orderId}
          action="approve"
          fields={[reason]}
          description="A aprovação avalia o crédito e cria a demanda. Ela não gera recebimento."
        />
      ) : null}
      {actions.includes("reject") ? (
        <SalesAction
          organizationId={organizationId}
          label="Rejeitar pedido"
          permission={PERMISSIONS.salesOrdersApprove}
          operation="order"
          id={orderId}
          action="reject"
          fields={[reason]}
        />
      ) : null}
      {actions.includes("reserve") ? (
        <SalesAction
          organizationId={organizationId}
          label="Reservar estoque"
          permission={PERMISSIONS.reservationsCreate}
          operation="reserve"
          id={orderId}
          fields={[sourceField]}
          description="A reserva torna a mercadoria indisponível para os demais pedidos, sem baixar estoque."
        />
      ) : null}
      {actions.includes("create_fulfillment") ? (
        <SalesAction
          organizationId={organizationId}
          label="Criar separação"
          permission={PERMISSIONS.fulfillmentManage}
          operation="fulfillment_create"
          id={orderId}
          fields={[sourceField]}
          items={toActionItems(items)}
          description="Informe quanto sair de cada item. Separar não baixa estoque."
        />
      ) : null}
      {actions.includes("close") ? (
        <SalesAction
          organizationId={organizationId}
          label="Encerrar pedido"
          permission={PERMISSIONS.salesOrdersUpdate}
          operation="order"
          id={orderId}
          action="close"
          fields={[reason]}
          description="Encerrar consolida o histórico; não apaga expedição nem devolução."
        />
      ) : null}
      {open && !actions.includes("cancel") ? null : null}
      {actions.includes("cancel") ? (
        <SalesAction
          organizationId={organizationId}
          label="Cancelar pedido"
          permission={PERMISSIONS.salesOrdersCancel}
          operation="order"
          id={orderId}
          action="cancel"
          fields={[reason]}
          description="Cancelar libera reservas e fecha o pedido. O que já foi expedido permanece no histórico."
        />
      ) : null}
    </div>
  );
}

function Fulfillments({
  organizationId,
  orderId,
  fulfillments,
  tasks,
  picks,
}: {
  organizationId: string;
  orderId: string;
  fulfillments: Row[];
  tasks: Row[];
  picks: Row[];
}) {
  if (fulfillments.length === 0) {
    return (
      <EmptyState
        title="Nenhuma separação criada"
        description="A separação é criada a partir de um pedido aprovado e é o que prepara a mercadoria para expedição."
      />
    );
  }
  return (
    <section className="space-y-3">
      <h2 className="text-lg font-semibold">Separação, conferência e embalagem</h2>
      {fulfillments.map((fulfillment) => {
        const status = text(fulfillment.status);
        const task = tasks.find((row) => text(row.fulfillment_order_id) === text(fulfillment.id));
        const taskPicks = picks.filter((row) => text(row.picking_task_id) === text(task?.id));
        return (
          <Card key={text(fulfillment.id)}>
            <CardHeader>
              <CardTitle className="text-base">
                {str(fulfillment.fulfillment_number)} · {fulfillmentStatusLabel(status)}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="flex flex-wrap gap-2">
                {fulfillmentActions(status).map((action) => (
                  <SalesAction
                    key={action.action}
                    organizationId={organizationId}
                    label={action.label}
                    permission={action.permission}
                    operation="fulfillment"
                    id={text(fulfillment.id)}
                    action={action.action}
                  />
                ))}
                {status === "PICKING" ? (
                  <SalesAction
                    organizationId={organizationId}
                    label="Ler código de barras / SKU"
                    permission={PERMISSIONS.pickingExecute}
                    operation="scan"
                    id={text(task?.id)}
                    fields={[
                      { key: "code", label: "Código de barras ou SKU", required: true },
                      { key: "quantity", label: "Quantidade", type: "number", required: true },
                    ]}
                    initial={{ quantity: 1 }}
                    description="Cada leitura soma à quantidade separada. Separar não baixa estoque."
                  />
                ) : null}
                {text(task?.status) === "PICKED" ? (
                  <SalesAction
                    organizationId={organizationId}
                    label="Conferir quantidades"
                    permission={PERMISSIONS.pickingConfirm}
                    operation="confirm"
                    id={text(task?.id)}
                    items={taskPicks.map((pick) => ({
                      id: text(pick.id),
                      label: `${str(pick.sku_snapshot)} — separado: ${numeric(pick.picked_quantity)}`,
                    }))}
                    itemField="picking_task_item_id"
                    quantityField="confirmed_quantity"
                    description="A diferença entre separado e conferido vira ocorrência; a conferência não altera o estoque."
                  />
                ) : null}
                {status === "PACKING" ? (
                  <SalesAction
                    organizationId={organizationId}
                    label="Registrar embalagem"
                    permission={PERMISSIONS.packingManage}
                    operation="pack"
                    id={text(fulfillment.id)}
                    items={taskPicks.map((pick) => ({ id: text(pick.id), label: str(pick.sku_snapshot) }))}
                    itemField="picking_task_item_id"
                    fields={[
                      { key: "gross_weight_kg", label: "Peso medido (kg)", type: "number" },
                      { key: "length_cm", label: "Comprimento (cm)", type: "number" },
                      { key: "width_cm", label: "Largura (cm)", type: "number" },
                      { key: "height_cm", label: "Altura (cm)", type: "number" },
                    ]}
                    description="Registre o que foi medido. Peso e dimensões nunca são estimados pelo sistema."
                  />
                ) : null}
                {status === "READY_FOR_SHIPMENT" ? (
                  <SalesAction
                    organizationId={organizationId}
                    label="Criar expedição"
                    permission={PERMISSIONS.shipmentsCreate}
                    operation="shipment_create"
                    id={orderId}
                    fixed={{ fulfillment_order_id: text(fulfillment.id) } as Row}
                    fields={[
                      {
                        key: "carrier_id",
                        label: "Transportadora",
                        hint: "Opcional: a expedição pode ser criada sem transportadora definida.",
                      },
                      { key: "tracking_code", label: "Código de rastreio" },
                      { key: "expected_delivery_at", label: "Entrega prevista", type: "datetime-local" },
                    ]}
                    description="A expedição é criada como rascunho pronta; a baixa de estoque acontece ao despachar."
                  />
                ) : null}
              </div>
              {task ? (
                <p className="text-sm text-muted-foreground">
                  Tarefa de separação: {pickingStatusLabel(task.status)}
                </p>
              ) : null}
              <Table
                data={taskPicks}
                columns={[
                  ["sku_snapshot", "SKU"],
                  ["requested_quantity", "Solicitado"],
                  ["picked_quantity", "Separado"],
                  ["confirmed_quantity", "Conferido"],
                ]}
              />
            </CardContent>
          </Card>
        );
      })}
    </section>
  );
}

function ShipmentActions({
  organizationId,
  orderId,
  shipment,
  shipmentItems,
}: {
  organizationId: string;
  orderId: string;
  shipment: Row;
  shipmentItems: Row[];
}) {
  const status = text(shipment.status);
  return (
    <div className="flex flex-wrap gap-2">
      {status === "READY" ? (
        <SalesAction
          organizationId={organizationId}
          label="Confirmar expedição"
          permission={PERMISSIONS.shipmentsDispatch}
          operation="dispatch"
          id={text(shipment.id)}
          description="Despachar dá a baixa oficial no estoque. Repetir a chamada não duplica a baixa."
        />
      ) : null}
      {isOneOf(status, IN_TRANSIT_SHIPMENT_STATUS) ? (
        <>
          <SalesAction
            organizationId={organizationId}
            label="Registrar rastreio"
            permission={PERMISSIONS.shipmentsDispatch}
            operation="shipment"
            action="track"
            id={text(shipment.id)}
            fields={[{ key: "tracking_code", label: "Código de rastreio", required: true }]}
          />
          <SalesAction
            organizationId={organizationId}
            label="Registrar recebedor"
            permission={PERMISSIONS.shipmentsConfirmDelivery}
            operation="shipment"
            action="proof"
            id={text(shipment.id)}
            fixed={{ proof_type: "SIGNATURE" } as Row}
            fields={[
              { key: "signature_name", label: "Nome do recebedor", required: true },
              { key: "notes", label: "Evidência / observações", type: "textarea", required: true },
            ]}
            description="Registro manual de evidência. Não há upload de foto ou assinatura digital."
          />
          <SalesAction
            organizationId={organizationId}
            label="Confirmar entrega"
            permission={PERMISSIONS.shipmentsConfirmDelivery}
            operation="shipment"
            action="deliver"
            id={text(shipment.id)}
            description="Confirmar entrega não mexe no saldo: a baixa já ocorreu na expedição."
          />
        </>
      ) : null}
      {isOneOf(status, DELIVERED_SHIPMENT_STATUS) ? (
        <SalesAction
          organizationId={organizationId}
          label="Solicitar devolução"
          permission={PERMISSIONS.returnsCreate}
          operation="return_create"
          id={orderId}
          fixed={{ shipment_id: text(shipment.id) } as Row}
          fields={[{ key: "reason", label: "Motivo", type: "textarea", required: true }]}
          items={shipmentItems.map((item) => ({
            id: text(item.sales_order_item_id),
            label: `${str(item.sku_snapshot)} — entregue: ${numeric(item.delivered_quantity)}`,
            pending: numeric(item.delivered_quantity) - numeric(item.returned_quantity),
          }))}
          description="Informe o que está voltando. O ajuste financeiro fica como solicitação, sem execução automática."
        />
      ) : null}
    </div>
  );
}

function Returns({
  organizationId,
  returns,
  returnItems,
  locationChoices,
}: {
  organizationId: string;
  returns: Row[];
  returnItems: Row[];
  locationChoices: { key: string; label: string }[];
}) {
  return (
    <Section
      title="Devoluções"
      description="Receber devolução devolve mercadoria ao estoque. Destino diferente de revendável exige quarentena ou inspeção."
    >
      {returns.length === 0 ? (
        <EmptyState
          title="Nenhuma devolução"
          description="A devolução é criada a partir de uma expedição entregue."
        />
      ) : (
        <div className="space-y-3">
          {returns.map((entry) => {
            const status = text(entry.status);
            const items = returnItems.filter(
              (row) => text(row.customer_return_id) === text(entry.id),
            );
            return (
              <Card key={text(entry.id)}>
                <CardHeader>
                  <CardTitle className="text-base">
                    {str(entry.return_number)} · {returnStatusLabel(status)}
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div className="flex flex-wrap gap-2">
                    {status === "DRAFT" ? (
                      <SalesAction
                        organizationId={organizationId}
                        label="Submeter devolução"
                        permission={PERMISSIONS.returnsCreate}
                        operation="return"
                        id={text(entry.id)}
                        action="submit"
                      />
                    ) : null}
                    {status === "PENDING_APPROVAL" ? (
                      <SalesAction
                        organizationId={organizationId}
                        label="Aprovar devolução"
                        permission={PERMISSIONS.returnsApprove}
                        operation="return"
                        id={text(entry.id)}
                        action="approve"
                        fields={[{ key: "reason", label: "Motivo", type: "textarea", required: true }]}
                      />
                    ) : null}
                    {status === "APPROVED" ? (
                      <SalesAction
                        organizationId={organizationId}
                        label="Receber devolução"
                        permission={PERMISSIONS.returnsReceive}
                        operation="return"
                        id={text(entry.id)}
                        action="receive"
                        fields={[
                          {
                            key: "destination_location_id",
                            label: "Local de destino",
                            required: true,
                            options: locationChoices.map((choice) => choice.key),
                            optionLabels: Object.fromEntries(
                              locationChoices.map((choice) => [choice.key, choice.label]),
                            ),
                          },
                          {
                            key: "destination",
                            label: "Destinação",
                            required: true,
                            options: ["SELLABLE", "QUARANTINE", "INSPECTION"],
                            optionLabels: {
                              SELLABLE: "Revendável",
                              QUARANTINE: "Quarentena",
                              INSPECTION: "Inspeção",
                            },
                          },
                        ]}
                        items={items.map((item) => ({
                          id: text(item.id),
                          label: str(item.sku_snapshot),
                        }))}
                        itemField="customer_return_item_id"
                        description="Mercadoria danificada ou com defeito não pode ir para estoque revendável."
                      />
                    ) : null}
                    {status === "RECEIVED" || status === "INSPECTED" ? (
                      <SalesAction
                        organizationId={organizationId}
                        label="Concluir devolução"
                        permission={PERMISSIONS.returnsCreate}
                        operation="return"
                        id={text(entry.id)}
                        action="complete"
                        fields={[{ key: "reason", label: "Motivo", type: "textarea", required: true }]}
                      />
                    ) : null}
                  </div>
                  <Table
                    data={items}
                    columns={[
                      ["sku_snapshot", "SKU"],
                      ["requested_quantity", "Solicitado"],
                      ["received_quantity", "Recebido"],
                      ["destination", "Destinação"],
                    ]}
                    render={(row) => returnDestinationLabel(row.destination)}
                  />
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </Section>
  );
}

function Section({
  title,
  description,
  children,
}: {
  title: string;
  description: string;
  children: React.ReactNode;
}) {
  return (
    <section className="space-y-3">
      <div>
        <h2 className="text-lg font-semibold">{title}</h2>
        <p className="text-sm text-muted-foreground">{description}</p>
      </div>
      {children}
    </section>
  );
}

function Table({
  data,
  columns,
  render,
  children,
}: {
  data: Row[];
  columns: [string, string][];
  render?: (row: Row) => string;
  children?: (row: Row) => React.ReactNode;
}) {
  if (data.length === 0) {
