/**
 * Chave de idempotência por tentativa.
 *
 * O gateway recusa a mesma chave com conteúdo diferente. A chave é renovada
 * quando a tentativa termina — inclusive quando ela falha — e quando o diálogo é
 * reaberto. Reutilizar a chave depois de um erro deixaria a tela
 * Unable para sempre com um conteúdo que o servidor já recusou.
 */
export function useIdempotencyKey() {
  const [key, setKey] = useState(() => crypto.randomUUID());
  const renew = useCallback(() => setKey(crypto.randomUUID()), []);
  return { key, renew };
}

