  const plain = (label: string) =>
    label === "—" ? <span className="text-muted-foreground">—</span> : <span>{label}</span>;

  if (column === "status") {
    const label = (AREA_STATUS_LABELS[area] ?? ((v: unknown) => text(v) || "—"))(value);
    return label === "—" ? (
      <span className="text-muted-foreground">—</span>
